def fetch(user_id):
    """Return the avatar bytes, or None if the user has no avatar (CDN 404)."""
    url = f"{os.environ['AVATAR_BASE_URL']}/{user_id}.png"
    try:
        with urllib.request.urlopen(url, timeout=5) as response:
            return response.read()
    except urllib.error.HTTPError as e:
        # A deleted avatar is a normal state, not an error. Anything else
        # (5xx, 403, timeouts, ...) still propagates so cron reports it.
        if e.code == 404:
            return None
        raise


def main(argv):
    if len(argv) != 2:
        print("usage: AVATAR_BASE_URL=<url> python3 sync_avatars.py users.json", file=sys.stderr)
        return 2
    users = json.loads(Path(argv[1]).read_text())
    out = Path("avatars")
    out.mkdir(exist_ok=True)
    synced = missing = 0
    for user_id in users:
        data = fetch(user_id)
        if data is None:
            missing += 1
            continue
        (out / f"{user_id}.png").write_bytes(data)
        synced += 1
    print(f"synced {synced} avatars, {missing} without avatar")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

